import random

def generate_numbers(target, min_val=0, max_val=100, max_iterations=1000):
    iterations = 0
    numbers = []

    while iterations < max_iterations:
        number = random.randint(min_val, max_val) if not numbers else random.uniform(max(min_val, target - sum(numbers)), min(max_val, target - min(numbers)))
        numbers.append(number)

        if sum(numbers) == target:
            break
        elif sum(numbers) > target:
            numbers = numbers[:-1]
        iterations += 1

    if iterations == max_iterations:
        return None
    else:
        return numbers

