def convertTemp(value, toUnit):
    if toUnit == 'f':
        return value * 9/5 + 32
    elif toUnit == 'c':
        return (value - 32) * 5/9
    else:
        return "Invalid unit. Please use 'f' for Fahrenheit and 'c' for Celsius."

